solution:
from bisect import bisect_left, bisect_right

def solve_tick_ranges(text):
    v = text.split()
    n, q = int(v[0]), int(v[1])
    ticks = [int(x) for x in v[2:2 + n]]
    out = []
    for t in map(int, v[2 + n:2 + n + q]):
        lo = bisect_left(ticks, t)
        if lo < n and ticks[lo] == t:
            out.append(f'{lo} {bisect_right(ticks, t) - 1}')
        else:
            out.append('-1 -1')
    return '\n'.join(out)

